// Nó "Cruzar perfis" (Code, modo: Run Once for All Items)
// Entrada: o CSV de investimentos vindo do nó "Ler investimentos (CSV)"
//          e a lista de clientes recebida pelo nó "Webhook".
// Saída:   um item por cliente, com o produto recomendado e a mensagem.

const csv = $input.first().json.data;
const corpo = $('Webhook').first().json.body || {};
const clientes = Array.isArray(corpo) ? corpo : (corpo.clientes || []);

// Templates fixos por perfil (MVP)
const TEMPLATES = {
  conservador: {
    foco: 'renda fixa e segurança',
    fechamento: 'São opções de baixo risco, ideais para proteger seu patrimônio e manter liquidez.',
  },
  moderado: {
    foco: 'um mix equilibrado entre renda fixa e renda variável',
    fechamento: 'Assim você busca um retorno acima da média sem abrir mão de parte da segurança.',
  },
  arrojado: {
    foco: 'ações e produtos com maior potencial de retorno',
    fechamento: 'Lembre-se: renda variável oscila mais, então pense no longo prazo.',
  },
};

// ---------- funções auxiliares ----------
function lerCsv(texto) {
  const linhas = String(texto || '').trim().split(/\r?\n/).filter(l => l.trim());
  const cabecalho = linhas.shift().split(',').map(c => c.trim());
  return linhas.map(linha => {
    const valores = linha.split(',');
    const item = {};
    cabecalho.forEach((col, i) => { item[col] = (valores[i] || '').trim(); });
    item.minimo = Number(item.minimo) || 0;
    return item;
  });
}

// "R$ 12.500,00" -> 12500
function paraNumero(saldo) {
  if (typeof saldo === 'number') return saldo;
  const limpo = String(saldo || '').replace(/[^\d,]/g, '').replace(',', '.');
  return Number(limpo) || 0;
}

function brl(valor) {
  return 'R$ ' + valor.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

// "13.0%" -> 13 ; "Variável" ou "IPCA+6.0%" -> null (não comparável)
function taxaFixa(rentabilidade) {
  const m = /^([\d.]+)%$/.exec(rentabilidade);
  return m ? Number(m[1]) : null;
}

function descrever(p) {
  return `${p.produto} (rentabilidade ${p.rentabilidade}, mínimo ${brl(p.minimo)})`;
}

// ---------- cruzamento ----------
const investimentos = lerCsv(csv);

return clientes.map(cliente => {
  const nome = String(cliente.nome || '').trim();
  const primeiroNome = nome.split(' ')[0] || 'cliente';
  const perfil = String(cliente.perfil || '').trim();
  const chave = perfil.toLowerCase();
  const saldo = paraNumero(cliente.saldo);
  const template = TEMPLATES[chave];

  const base = {
    nome,
    email: cliente.email,
    perfil,
    saldo,
    saldo_formatado: brl(saldo),
  };

  // Perfil desconhecido: não arrisca uma recomendação
  if (!template) {
    return { json: { ...base, produto_recomendado: null, opcoes: [], opcoes_detalhe: [],
      mensagem: `Olá, ${primeiroNome}! Não encontramos seu perfil de investidor atualizado. ` +
        'Responda nosso questionário de perfil para receber recomendações personalizadas.',
      origem: 'template' } };
  }

  // Produtos do perfil que cabem no saldo do cliente
  const elegiveis = investimentos
    .filter(p => p.perfil.toLowerCase() === chave && p.minimo <= saldo);

  if (elegiveis.length === 0) {
    return { json: { ...base, produto_recomendado: null, opcoes: [], opcoes_detalhe: [],
      mensagem: `Olá, ${primeiroNome}! Seu perfil é ${perfil}, com foco em ${template.foco}. ` +
        `Com o saldo atual de ${brl(saldo)}, ainda não atingimos a aplicação mínima dos produtos ` +
        'do seu perfil. Que tal fazer novos aportes? Assim que possível, enviamos as melhores opções.',
      origem: 'template' } };
  }

  // Destaque: maior taxa fixa; se não houver taxa fixa (renda variável), o de maior mínimo que cabe no saldo
  const ordenados = [...elegiveis].sort((a, b) => {
    const ta = taxaFixa(a.rentabilidade), tb = taxaFixa(b.rentabilidade);
    if (ta !== null && tb !== null) return tb - ta;
    if (ta !== null) return -1;
    if (tb !== null) return 1;
    return b.minimo - a.minimo;
  });
  const destaque = ordenados[0];
  const outras = ordenados.slice(1);

  let mensagem = `Olá, ${primeiroNome}! Como seu perfil é ${perfil}, nossa sugestão tem foco em ${template.foco}. ` +
    `Com seu saldo de ${brl(saldo)}, recomendamos ${descrever(destaque)}.`;
  if (outras.length) {
    mensagem += ` Outras opções do seu perfil que cabem no seu saldo: ${outras.map(p => p.produto).join(', ')}.`;
  }
  mensagem += ` ${template.fechamento}`;

  return { json: { ...base,
    produto_recomendado: destaque.produto,
    opcoes: ordenados.map(p => p.produto),
    opcoes_detalhe: ordenados.map(descrever),
    mensagem,
    origem: 'template' } };
});

