// Nó "Montar resposta": junta o texto da IA com os dados do cliente.
// Se a IA falhar ou vier vazia, usa a mensagem do template como plano B.
const clientes = $('Cruzar perfis').all();

return $input.all().map((item, i) => {
  const cliente = clientes[i].json;
  const textoIa = String(item.json.output || '').trim();
  return {
    json: {
      ...cliente,
      mensagem: textoIa || cliente.mensagem,
      mensagem_template: cliente.mensagem,
      origem: textoIa ? 'ia' : 'template',
    },
  };
});
